import numpy as np
W1, W2, W3 = W['W1'], W['W2'], W['W3']
# linearized input -> logit map (matrix product only, no forward pass)
Weff = W1 @ W2 @ W3  # 500 x 5
names = ['noop','up','down','left','right']
maps = {i: Weff[:, i] for i in range(5)}

def cos(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-12)

print("Action-map cosine similarities:")
for i in range(5):
    for j in range(i+1, 5):
        print(f"{names[i]:5s}-{names[j]:5s}: {cos(maps[i], maps[j]): .3f}")

# reshape to row, col, channel, action
Weff_grid = Weff.reshape(10, 10, 5, 5)
print("\nPer-channel influence norm (over grid):")
for i in range(5):
    norms = [np.linalg.norm(Weff_grid[:, :, c, i]) for c in range(5)]
    print(f"{names[i]:5s}: " + " ".join(f"{n:8.2f}" for n in norms))

for act in [1, 2]:
    diff = maps[act] - maps[0]
    print(f"\n{names[act]} - noop: ||diff||={np.linalg.norm(diff):.3f}, "
          f"ratio={np.linalg.norm(diff)/np.linalg.norm(maps[0]):.3f}")
